scripts.卢青.txt:
//和卢青对话

	If ($Event == 800) @Event800;
	If ($Event == 820) @Event820;
	
@Event800:
	If ($Talkluq == 0) @Talkluq0;
	If ($Talkluq == 1) @Talkluq1;
 @Talkluq0:
	Say("独孤剑：师弟？你怎么来了。", 6);
	Say("卢青：师兄，可想死我们了。上次我走了后，又听说你被金国人打伤了，大家一直很担心。后来无虚大师要我来这里等你，我就来这里了。", 83);
	Say("独孤剑：无虚大师？", 8);
	Say("卢青：对呀，大师就在那边。师兄，你一定能夺得武林盟主。", 83);
	Assign($Talkluq, 1);
	Return;
 @Talkluq1:
	Say("卢青：师兄，你一定能夺得武林盟主的。", 83);
	Return;
	
@Event820:
	Say("卢青：师兄，真是太好了！师傅在天有灵，也会为师兄高兴的。", 83);
	Return;

scripts.方雷.txt:
//和方雷对话

