scripts.李啸.txt:
//和李啸对话

	If ($Event == 820) @Event820;
	
	Say("李啸：当今武林的后起之秀中，五大剑客名列第三第四的张如梦和南宫彩虹最富有传奇色彩。这两位分别是“飞剑客”张风的公子和“天剑客”南宫灭的女儿。张风和南宫灭本是死对头，但他们两人的儿女关系却非同寻常，真是难以想象！一种传说是张如梦和南宫彩虹两人在剑门关殉情自杀，另一种传说是二人远走高飞，退隐江湖了，也不知哪个是真，哪个是假？", 78);
	Return;
	
@Event820:
	Say("李啸：独孤盟主，武艺高绝，在下输的心服口服。今后，李啸一定跟随盟主左右，共抗金敌。", 78);
	Return;

